\":{\"file\":\"meta/version_history.json\",\"size_kb\":0.4,\"tags\":[\"version\",\"history\",\"changes\"],\"description\":\"История версий философии\"},\"roadmap\":{\"file\":\"meta/roadmap.json\",\"size_kb\":0.5,\"tags\":[\"roadmap\",\"milestones\",\"plan\"],\"description\":\"Дорожная карта развития\"}},\"load_priority\":\"low\"}},\"usage\":{\"for_sr\":\"Используй для доступа к философским основам. Загружай только нужные сегменты.\",\"workflow\":[\"1. При философском диалоге: загрузи essence.json\",\"2. При обсуждении Ахимсы: загрузи ahimsa_principle.json\",\"3. Для свидетельств: загрузи testimonies/\",\"4. Для истории: загрузи meta/\"],\"total_size\":\"4.5KB → 9 файлов <1KB каждый\",\"migration_source\":\"simbiosis/philosophy.json\"},\"registry\":{\"total_files\":9,\"total_size_kb\":5.8,\"max_segment_kb\":0.7,\"segments\":[\"blocks\",\"testimonies\",\"meta\"],\"migration_status\":\"in_progress\"}}",
